#!/usr/bin/env python3
"""Добавляет светлую тему и кнопку смены темы в ВАШИ index.html и globe.html геотренажёра.

Запуск из папки репозитория:   python3 apply_geotrainer_theme.py
или с путём:                   python3 apply_geotrainer_theme.py путь/к/geotrainer

Перед правкой рядом сохраняются копии *.bak. Если какой-то фрагмент в вашем файле
не найден (вы его меняли), скрипт останавливается с понятным сообщением и ничего не пишет.
Файл theme.js нужно положить в ту же папку отдельно (он в архиве).
"""
import os, shutil, sys

PATCH_INDEX = 's = open(p, encoding=\'utf-8\').read()\n\n\ndef sub(old, new, count=1):\n    global s\n    n = s.count(old)\n    assert n == count, (old[:80], n)\n    s = s.replace(old, new)\n\n\n# ---------- <head>\nsub("""<meta name="theme-color" content="#08090b">\n""", """<meta name="theme-color" content="#08090b">\n<meta name="color-scheme" content="dark light">\n<script src="theme.js"></script>\n""")\n\n# ---------- переменные\nsub("""  --color-warn: #e5a921;\n""", """  --color-warn: #e5a921;\n\n  /* вспомогательные цвета, которые меняются вместе с темой сайта */\n  --header-bg: rgb(8 9 11 / .82);\n  --overlay: rgb(8 9 11 / .86);\n  --shadow-lg: 0 18px 48px rgb(0 0 0 / .45);\n  --shadow-xl: 0 24px 72px rgb(0 0 0 / .5);\n  --ok-ink: #6ef0b2; --bad-ink: #ff8e95;\n  --sw-border: #ffffff22;\n  color-scheme: dark;\n""")\nsub("--acc: var(--color-accent); --accink: #06080c; --sea-chip: #1a2a47;\\n}", """--acc: var(--color-accent); --accink: #06080c; --sea-chip: #1a2a47;\n}\n\n/* ---------- Светлая тема сайта ----------\n   Включается атрибутом data-theme="light" на <html> (его ставит theme.js).\n   Цвета самой карты задаются отдельно — «Оформление карты» на главной. */\n:root[data-theme=\'light\'] {\n  --color-background: #f5f7fa;\n  --color-surface: #ffffff;\n  --color-surface-elevated: #edf1f7;\n  --color-text-primary: #12161d;\n  --color-text-secondary: #566070;\n  --color-accent: #2c5fd0;\n  --color-accent-hover: #1b43a6;\n  --color-border: #d3d9e3;\n  --color-ok: #1f9d68;\n  --color-bad: #d6404a;\n  --color-warn: #c98a0a;\n\n  --header-bg: rgb(245 247 250 / .85);\n  --overlay: rgb(245 247 250 / .88);\n  --shadow-lg: 0 18px 48px rgb(20 33 61 / .18);\n  --shadow-xl: 0 24px 72px rgb(20 33 61 / .22);\n  --ok-ink: #0e6b43; --bad-ink: #a8222b;\n  --sw-border: #00000026;\n  --accink: #ffffff;\n  --sea-chip: #dbe7fb;\n  color-scheme: light;\n}""")\nsub("-webkit-text-size-adjust: 100%; color-scheme: dark; background: var(--color-background); }", "-webkit-text-size-adjust: 100%; background: var(--color-background); }")\n\n# ---------- жёсткие цвета -> переменные\nsub("height: var(--header-h); background: rgb(8 9 11 / .82); backdrop-filter", "height: var(--header-h); background: var(--header-bg); backdrop-filter")\nsub("border: 1px solid #ffffff22; flex: none; }", "border: 1px solid var(--sw-border); flex: none; }")\nsub("box-shadow: 0 18px 48px rgb(0 0 0 / .45); z-index: 4; }", "box-shadow: var(--shadow-lg); z-index: 4; }", count=2)\nsub("box-shadow: 0 18px 48px rgb(0 0 0 / .4); }", "box-shadow: var(--shadow-lg); }")\nsub("background: rgb(59 196 138 / .22); color: #6ef0b2;", "background: rgb(59 196 138 / .22); color: var(--ok-ink);")\nsub("background: rgb(239 91 100 / .2); color: #ff8e95;", "background: rgb(239 91 100 / .2); color: var(--bad-ink);")\nsub("background: rgb(8 9 11 / .86); backdrop-filter: blur(8px);", "background: var(--overlay); backdrop-filter: blur(8px);")\nsub("box-shadow: 0 24px 72px rgb(0 0 0 / .5); }", "box-shadow: var(--shadow-xl); }")\n\n# ---------- кнопка темы\nsub("""/* ---------- Кнопки ---------- */""", """/* кнопка смены темы (шапка и панель игры) */\n.theme-toggle { display: inline-grid; place-items: center; flex: none; width: 44px; height: 44px; padding: 0; border: 1px solid var(--color-border); border-radius: 50%; background: transparent; color: var(--color-text-secondary); transition: color .25s var(--ease), border-color .25s var(--ease), background-color .25s var(--ease); }\n.theme-toggle:hover { color: var(--color-text-primary); border-color: var(--color-accent); background: var(--color-surface-elevated); }\n.theme-toggle svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n.theme-toggle .icon-moon { display: none; }\n:root[data-theme=\'light\'] .theme-toggle .icon-sun { display: none; }\n:root[data-theme=\'light\'] .theme-toggle .icon-moon { display: block; }\n.theme-toggle--bar { width: 38px; height: 38px; }\n.theme-toggle--bar svg { width: 18px; height: 18px; }\n/* короткая плавная смена цветов при нажатии на кнопку */\nhtml.theme-anim, html.theme-anim *, html.theme-anim *::before, html.theme-anim *::after { transition: background-color .3s var(--ease), color .3s var(--ease), border-color .3s var(--ease), fill .3s var(--ease), stroke .3s var(--ease), box-shadow .3s var(--ease) !important; }\n@media (prefers-reduced-motion: reduce) { html.theme-anim, html.theme-anim *, html.theme-anim *::before, html.theme-anim *::after { transition: none !important; } }\n@media (max-width: 480px) { .header-actions { gap: 10px; } .theme-toggle { width: 40px; height: 40px; } }\n\n/* ---------- Кнопки ---------- */""")\n\n# ---------- разметка шапки (раньше в index.html её не было, а CSS .site-header уже был)\nSUN = \'<svg class="icon-sun" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="4"/><path d="M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.6 1.6M17.1 17.1l1.6 1.6M18.7 5.3l-1.6 1.6M6.9 17.1l-1.6 1.6"/></svg>\'\nMOON = \'<svg class="icon-moon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M20.5 14.2A8.5 8.5 0 0 1 9.8 3.5a8.5 8.5 0 1 0 10.7 10.7Z"/></svg>\'\nsub("""</style></head><body>\n<div id="home"></div>""", f"""</style></head><body>\n<header class="site-header" id="site-header"><div class="container">\n <a class="brand" href="index.html" aria-label="Геотренажёр">\n  <svg class="brand-mark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/></svg>\n  <span class="brand-name">Геотренажёр</span>\n </a>\n <div class="header-actions">\n  <nav class="nav" aria-label="nmchv.ru"><a href="https://nmchv.ru" rel="noopener">nmchv.ru</a></nav>\n  <button class="theme-toggle" type="button" data-theme-toggle aria-label="Включить светлую тему" title="Включить светлую тему">{SUN}{MOON}</button>\n </div>\n</div></header>\n<div id="home"></div>""")\n\n# кнопка в панели игры (там основная шапка скрыта)\nsub("""  <button class="btn ghost sm" id="skip">Пропустить</button><button class="btn ghost sm" id="stop">Завершить</button></div>""",\n    f"""  <button class="btn ghost sm" id="skip">Пропустить</button><button class="btn ghost sm" id="stop">Завершить</button>\n  <button class="theme-toggle theme-toggle--bar" type="button" data-theme-toggle aria-label="Включить светлую тему" title="Включить светлую тему">{SUN}{MOON}</button></div>""")\n\n# ---------- «Оформление карты» по умолчанию следует теме сайта\nsub("""let THEME=\'dark\';try{THEME=sessionStorage.getItem(\'gt_theme\')||\'dark\'}catch(e){}\nif(!THEMES.some(t=>t.id===THEME))THEME=\'dark\';""", """// оформление карты: пока посетитель не выбрал своё, карта следует теме сайта (тёмная / светлая)\nlet THEME=\'dark\',THEME_AUTO=true;try{const st=sessionStorage.getItem(\'gt_theme\');if(st){THEME=st;THEME_AUTO=false}}catch(e){}\nif(THEME_AUTO)THEME=document.documentElement.getAttribute(\'data-theme\')===\'light\'?\'light\':\'dark\';\nif(!THEMES.some(t=>t.id===THEME)){THEME=\'dark\';THEME_AUTO=true}\nwindow.addEventListener(\'nmchv:themechange\',e=>{if(!THEME_AUTO)return;const t=e.detail&&e.detail.theme===\'light\'?\'light\':\'dark\';if(t===THEME)return;THEME=t;if(CURV===\'game\')applyTheme();else if(CURV===\'home\')home(true)});""")\nsub("on:{click:()=>{THEME=t.id;try{sessionStorage.setItem(\'gt_theme\',THEME)}catch(e){}home(true)}}", "on:{click:()=>{THEME=t.id;THEME_AUTO=false;try{sessionStorage.setItem(\'gt_theme\',THEME)}catch(e){}home(true)}}")\n\n# после выбора языка подписи кнопки темы перечитываем\nsub("document.documentElement.lang=LANG;if(LANG===\'en\'){", "document.documentElement.lang=LANG;if(window.NmchvTheme)NmchvTheme.refresh();if(LANG===\'en\'){")\n\nopen(p, \'w\', encoding=\'utf-8\').write(s)\nprint(\'index ok\')\n'
PATCH_GLOBE = 's = open(p, encoding=\'utf-8\').read()\n\n\ndef sub(old, new, count=1):\n    global s\n    n = s.count(old)\n    assert n == count, (old[:80], n)\n    s = s.replace(old, new)\n\n\n# ---------- <head>\nsub("""<meta name="theme-color" content="#050816">\n""", """<meta name="theme-color" content="#050816">\n<meta name="color-scheme" content="dark light">\n<script src="theme.js"></script>\n""")\n\n# ---------- переменные\nsub("""    --ok: #3bc48a; --bad: #ef5b64; --warn: #e5a921;\n  }""", """    --ok: #3bc48a; --bad: #ef5b64; --warn: #e5a921;\n    /* вспомогательные цвета, которые меняются вместе с темой */\n    --top-bg: rgb(14 18 27 / .92);\n    --toast-bg: rgb(23 28 39 / .94);\n    --chip-bg: rgb(8 12 24 / .85);\n    --scrim: rgb(2 4 12 / .72);\n    --on-acc: #06080c;\n    --ok-ink: #6ef0b2; --bad-ink: #ff8e95;\n    --card-shadow: 0 24px 72px rgb(0 0 0 / .55);\n    --ctrl-filter: invert(1) brightness(1.4);\n    --space-bg: radial-gradient(ellipse at 50% 50%, #070d22 0%, #040716 55%, #01020a 100%);\n    color-scheme: dark;\n  }\n  /* Светлая тема: включается атрибутом data-theme="light" на <html> (его ставит theme.js) */\n  :root[data-theme=\'light\'] {\n    --bg: #eaf2fa; --surface: #ffffff; --elev: #f1f5fa; --border: #cfd7e3;\n    --text: #12161d; --mute: #566070; --acc: #2c5fd0; --acc-h: #1b43a6;\n    --ok: #1f9d68; --bad: #d6404a; --warn: #c98a0a;\n    --top-bg: rgb(255 255 255 / .92);\n    --toast-bg: rgb(255 255 255 / .96);\n    --chip-bg: rgb(255 255 255 / .92);\n    --scrim: rgb(234 242 250 / .8);\n    --on-acc: #ffffff;\n    --ok-ink: #0e6b43; --bad-ink: #a8222b;\n    --card-shadow: 0 24px 72px rgb(20 33 61 / .22);\n    --ctrl-filter: none;\n    --space-bg: radial-gradient(ellipse at 50% 50%, #f4f9ff 0%, #e3eef9 55%, #d3e3f3 100%);\n    color-scheme: light;\n  }""")\n\n# ---------- жёсткие цвета -> переменные\nsub("background: rgb(14 18 27 / .92); border-bottom: 1px solid var(--border);", "background: var(--top-bg); border-bottom: 1px solid var(--border);")\nsub(".btn.pri { background: var(--acc); border-color: var(--acc); color: #06080c; font-weight: 600; }", ".btn.pri { background: var(--acc); border-color: var(--acc); color: var(--on-acc); font-weight: 600; }")\nsub("background: radial-gradient(ellipse at 50% 50%, #070d22 0%, #040716 55%, #01020a 100%); transition: opacity .25s; }", "background: var(--space-bg); transition: opacity .25s; }")\nsub("  #stars { position: absolute; inset: 0; width: 100%; height: 100%; }", """  #stars { position: absolute; inset: 0; width: 100%; height: 100%; }\n  :root[data-theme=\'light\'] #stars, :root[data-theme=\'light\'] #spacelab { display: none; }   /* звёзды только в тёмной теме */""")\nsub("background: rgb(23 28 39 / .94); border: 1px solid var(--border); border-radius: 999px;", "background: var(--toast-bg); border: 1px solid var(--border); border-radius: 999px;")\nsub("#toast.ok { border-color: var(--ok); color: #6ef0b2; }", "#toast.ok { border-color: var(--ok); color: var(--ok-ink); }")\nsub("#toast.bad { border-color: var(--bad); color: #ff8e95; }", "#toast.bad { border-color: var(--bad); color: var(--bad-ink); }")\nsub("background: rgb(8 12 24 / .85); border: 1px solid #3bc48a; white-space: nowrap; }", "background: var(--chip-bg); border: 1px solid #3bc48a; white-space: nowrap; }")\nsub(".maplibregl-ctrl button .maplibregl-ctrl-icon { filter: invert(1) brightness(1.4); }", ".maplibregl-ctrl button .maplibregl-ctrl-icon { filter: var(--ctrl-filter); }")\nsub("background: rgb(2 4 12 / .72); padding: 16px; }", "background: var(--scrim); padding: 16px; }")\nsub("box-shadow: 0 24px 72px rgb(0 0 0 / .55); }", "box-shadow: var(--card-shadow); }")\n\n# кнопка темы\nsub("  .card .row { display: flex; gap: 10px; margin-top: 18px; flex-wrap: wrap; }\\n</style>", """  .card .row { display: flex; gap: 10px; margin-top: 18px; flex-wrap: wrap; }\n\n  /* ---------- кнопка смены темы ---------- */\n  .theme-toggle { display: inline-grid; place-items: center; flex: none; width: 38px; height: 38px; padding: 0; margin-left: auto; border: 1px solid var(--border); border-radius: 50%; background: var(--elev); color: var(--mute); cursor: pointer; transition: color .2s, border-color .2s; }\n  .theme-toggle:hover { color: var(--text); border-color: var(--acc); }\n  .theme-toggle svg { width: 18px; height: 18px; display: block; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n  .theme-toggle .icon-moon { display: none; }\n  :root[data-theme=\'light\'] .theme-toggle .icon-sun { display: none; }\n  :root[data-theme=\'light\'] .theme-toggle .icon-moon { display: block; }\n  html.theme-anim, html.theme-anim *, html.theme-anim *::before, html.theme-anim *::after { transition: background-color .3s, color .3s, border-color .3s, box-shadow .3s !important; }\n  @media (prefers-reduced-motion: reduce) { html.theme-anim, html.theme-anim *, html.theme-anim *::before, html.theme-anim *::after { transition: none !important; } }\n</style>""")\n\nSUN = \'<svg class="icon-sun" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="4"/><path d="M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.6 1.6M17.1 17.1l1.6 1.6M18.7 5.3l-1.6 1.6M6.9 17.1l-1.6 1.6"/></svg>\'\nMOON = \'<svg class="icon-moon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M20.5 14.2A8.5 8.5 0 0 1 9.8 3.5a8.5 8.5 0 1 0 10.7 10.7Z"/></svg>\'\nsub("""  <label class="chk" title="Звёзды вокруг глобуса"><input type="checkbox" id="spacechk" checked> Звёзды</label>\n</div>""", f"""  <label class="chk" id="spacelab" title="Звёзды вокруг глобуса"><input type="checkbox" id="spacechk" checked> Звёзды</label>\n  <button class="theme-toggle" type="button" data-theme-toggle aria-label="Включить светлую тему" title="Включить светлую тему">{SUN}{MOON}</button>\n</div>""")\n\n# ---------- цвета самого глобуса\nsub("""  // ---------------------------------------------------------------- карта\n  function fail(msg)""", """  // ---------------------------------------------------------------- цвета глобуса по теме сайта\n  function palette() {\n    var light = document.documentElement.getAttribute(\'data-theme\') === \'light\';\n    return light ? {\n      sea: \'#a9cde6\', land: \'#eef1f5\', landHover: \'#c9dcfb\', line: \'#8398bb\',\n      river: \'#2a6ad1\', riverHover: \'#1b43a6\', dotHover: \'#1b43a6\', dotFalls: \'#2a8fd8\',\n      sky: { \'sky-color\': \'#cfe6fa\', \'horizon-color\': \'#f1f7fd\', \'fog-color\': \'#dbe9f6\' }\n    } : {\n      sea: \'#0b2342\', land: \'#2b3d58\', landHover: \'#46689f\', line: \'#7ea6ee\',\n      river: \'#3d8bff\', riverHover: \'#b9dcff\', dotHover: \'#ffffff\', dotFalls: \'#7fd1ff\',\n      sky: { \'sky-color\': \'#2a7de1\', \'horizon-color\': \'#9cc9ff\', \'fog-color\': \'#1e3a8a\' }\n    };\n  }\n  function skyOf(P) {\n    return {\n      \'sky-color\': P.sky[\'sky-color\'], \'sky-horizon-blend\': 0.5,\n      \'horizon-color\': P.sky[\'horizon-color\'], \'horizon-fog-blend\': 0.5,\n      \'fog-color\': P.sky[\'fog-color\'], \'fog-ground-blend\': 0.5,\n      \'atmosphere-blend\': [\'interpolate\', [\'linear\'], [\'zoom\'], 0, 1, 4, 1, 7, 0.4]\n    };\n  }\n  var STATE = function (name, v) { return [\'boolean\', [\'feature-state\', name], false]; };\n  function fillColor(P) { return [\'case\', STATE(\'ok\'), \'#3bc48a\', STATE(\'bad\'), \'#ef5b64\', STATE(\'rev\'), \'#e5a921\', STATE(\'hover\'), P.landHover, P.land]; }\n  function riverColor(P) { return [\'case\', STATE(\'ok\'), \'#3bc48a\', STATE(\'bad\'), \'#ef5b64\', STATE(\'rev\'), \'#e5a921\', STATE(\'hover\'), P.riverHover, P.river]; }\n  function dotColor(P) { return [\'case\', STATE(\'ok\'), \'#3bc48a\', STATE(\'bad\'), \'#ef5b64\', STATE(\'rev\'), \'#e5a921\', STATE(\'hover\'), P.dotHover, [\'==\', [\'get\', \'k\'], \'falls\'], P.dotFalls, \'#ffd166\']; }\n  function applyPalette() {\n    if (!map) return;\n    var P = palette();\n    try { map.setPaintProperty(\'sea\', \'background-color\', P.sea); } catch (e) {}\n    try { map.setSky(skyOf(P)); } catch (e) {}\n    try {\n      if (map.getLayer(\'fill\')) {\n        map.setPaintProperty(\'fill\', \'fill-color\', fillColor(P));\n        map.setPaintProperty(\'line\', \'line-color\', P.line);\n        map.setPaintProperty(\'rivers\', \'line-color\', riverColor(P));\n        map.setPaintProperty(\'dots\', \'circle-color\', dotColor(P));\n      }\n    } catch (e) {}\n  }\n  window.addEventListener(\'nmchv:themechange\', applyPalette);\n\n  // ---------------------------------------------------------------- карта\n  function fail(msg)""")\nsub("layers: [{ id: \'sea\', type: \'background\', paint: { \'background-color\': \'#0b2342\' } }]", "layers: [{ id: \'sea\', type: \'background\', paint: { \'background-color\': palette().sea } }]")\nsub("""      map.setSky({\n        \'sky-color\': \'#2a7de1\', \'sky-horizon-blend\': 0.5,\n        \'horizon-color\': \'#9cc9ff\', \'horizon-fog-blend\': 0.5,\n        \'fog-color\': \'#1e3a8a\', \'fog-ground-blend\': 0.5,\n        \'atmosphere-blend\': [\'interpolate\', [\'linear\'], [\'zoom\'], 0, 1, 4, 1, 7, 0.4]\n      });""", """      map.setSky(skyOf(palette()));""")\nsub("""  var STATE = function (name, v) { return [\'boolean\', [\'feature-state\', name], false]; };\n\n  map.on(\'load\'""", """  map.on(\'load\'""")\nsub("""    map.addLayer({ id: \'fill\', type: \'fill\', source: \'c\', paint: {\n      \'fill-color\': [\'case\', STATE(\'ok\'), \'#3bc48a\', STATE(\'bad\'), \'#ef5b64\', STATE(\'rev\'), \'#e5a921\', STATE(\'hover\'), \'#46689f\', \'#2b3d58\']\n    } });""", """    var P = palette();\n    map.addLayer({ id: \'fill\', type: \'fill\', source: \'c\', paint: { \'fill-color\': fillColor(P) } });""")\nsub("paint: { \'line-color\': \'#7ea6ee\', \'line-width\': 0.8, \'line-opacity\': 0.9 } });", "paint: { \'line-color\': P.line, \'line-width\': 0.8, \'line-opacity\': 0.9 } });")\nsub("""      \'line-color\': [\'case\', STATE(\'ok\'), \'#3bc48a\', STATE(\'bad\'), \'#ef5b64\', STATE(\'rev\'), \'#e5a921\', STATE(\'hover\'), \'#b9dcff\', \'#3d8bff\'],""", """      \'line-color\': riverColor(P),""")\nsub("""      \'circle-color\': [\'case\', STATE(\'ok\'), \'#3bc48a\', STATE(\'bad\'), \'#ef5b64\', STATE(\'rev\'), \'#e5a921\', STATE(\'hover\'), \'#ffffff\',\n        [\'==\', [\'get\', \'k\'], \'falls\'], \'#7fd1ff\', \'#ffd166\'],""", """      \'circle-color\': dotColor(P),""")\n\nopen(p, \'w\', encoding=\'utf-8\').write(s)\nprint(\'globe ok\')\n'


def run(path):
    for name, src in (('index.html', PATCH_INDEX), ('globe.html', PATCH_GLOBE)):
        f = os.path.join(path, name)
        if not os.path.exists(f):
            print('пропускаю (нет файла):', f)
            continue
        shutil.copy(f, f + '.bak')
        try:
            exec(compile("p = %r\n" % f + src, name, 'exec'), {})
        except AssertionError as e:
            shutil.copy(f + '.bak', f)
            print('ОШИБКА в %s: не найден ожидаемый фрагмент -> %s' % (name, e.args[0]))
            print('Файл не изменён. Покажите мне эту строку, и я подскажу правку вручную.')
            sys.exit(1)
    if not os.path.exists(os.path.join(path, 'theme.js')):
        print('Внимание: положите theme.js из архива в', path)
    print('Готово. Резервные копии: index.html.bak, globe.html.bak')


if __name__ == '__main__':
    run(sys.argv[1] if len(sys.argv) > 1 else '.')
